validator:
function validate(input) {
  const [{ Candidates = [] }] = input;
  const ids = new Set(), salaries = new Set();
  for (const [id, experience, salary] of Candidates) {
    if (id === null || experience === null || salary === null) return 'Every column is required.';
    if (ids.has(id)) return `employee_id ${id} appears twice.`;
    ids.add(id);
    if (experience !== 'Senior' && experience !== 'Junior') return `Unknown experience ${experience}.`;
    if (salary <= 0) return 'salary must be positive.';
    const key = `${experience}|${salary}`;
    if (salaries.has(key)) return `Two ${experience} candidates ask for ${salary}.`;
    salaries.add(key);
  }
  return null;
}

generator:
function generate(rand, size) {
  const small = size === 'small';
  const rows = small ? Math.floor(rand() * 9) : 2000;
  // Small salaries are round numbers so running totals often land exactly on the budget.
  const pool = [5000, 10000, 15000, 20000, 25000, 30000, 35000, 40000, 50000, 60000, 70000, 80000];
  const used = new Set(), Candidates = [];
  const ids = Array.from({ length: small ? 15 : 3000 }, (_, i) => i + 1);
  for (let i = ids.length - 1; i > 0; i--) { const j = Math.floor(rand() * (i + 1)); [ids[i], ids[j]] = [ids[j], ids[i]]; }
  for (let i = 0; i < rows; i++) {
    const experience = rand() < 0.5 ? 'Senior' : 'Junior';
    const draw = () => (small ? pool[Math.floor(rand() * pool.length)] : 100 + Math.floor(rand() * 100000));
    let salary = draw();
    // Large sets redraw a repeated salary; small sets simply skip the candidate.
    while (!small && used.has(`${experience}|${salary}`)) salary = draw();
    if (used.has(`${experience}|${salary}`)) continue;
    used.add(`${experience}|${salary}`);
    Candidates.push([ids[i], experience, salary]);
  }
  return [{ Candidates }];
}
